// Facture Stripe payée -> données de l'email « Votre facture BoostImpact » (18/11/2026). Une seule source : recopiée mot pour mot dans le nœud
// « Vérifier et traduire » de n8n/renom-stripe-webhook.json (n8n/build_stripe.py), juste après moteur/paiement/stripe.js, et dans le nœud
// « Lire la facture » de n8n/renom-facture-envoi.json (n8n/build_facture.py). Exécutée par moteur/tests/test_facture_envoi.js.
// Tout est rangé dans UN objet (FACTURE_STRIPE) : aucun nom de premier niveau ne se heurte à ceux de stripe.js ni de courriels.js dans le même nœud.
//
// Pourquoi : Stripe crée une facture à chaque paiement, mais les emails de Stripe aux clients sont coupés sur le compte BoostImpact (et sa langue
// par défaut est l'anglais) : sans cet envoi, le client ne reçoit pas sa facture.
// Règles : seulement invoice.paid ; seulement un paiement RÉEL (amount_paid > 0 : une facture à 0 €, essai ou code, ne donne aucun email, une
// facture réglée entièrement par le solde du client non plus) ; liens de la facture acceptés seulement en https sur un domaine de Stripe (le bouton
// de l'email et le téléchargement du PDF, fait avec l'identifiant « Stripe RENOM », ne partent jamais ailleurs).
// Champs lus sur l'objet Invoice de Stripe (docs.stripe.com/api/invoices/object ; NON CONFIRMÉ contre un vrai événement du compte, aucune page
// relue aujourd'hui : voir le compte rendu) : id (in_…), number, amount_paid (centimes), currency, customer, customer_email, hosted_invoice_url,
// invoice_pdf, status_transitions.paid_at, lines.data[].period {start, end}, lines.data[].amount, et l'abonnement lu aux deux endroits déjà
// utilisés par stripe.js (invoice.subscription, invoice.parent.subscription_details.subscription).
const FACTURE_STRIPE = (() => {
  const RE = { facture: /^in_[A-Za-z0-9]{6,}$/, abonnement: /^sub_[A-Za-z0-9]{6,}$/, client: /^cus_[A-Za-z0-9]{6,}$/, numero: /^[A-Za-z0-9][A-Za-z0-9-]{0,40}$/,
    email: /^[^\s@<>"',;]+@[^\s@<>"',;]+\.[^\s@<>"',;]{2,}$/ };
  const ident = x => (x && typeof x === "object" ? x.id : x) || null;
  const accepte = (v, re) => (typeof v === "string" && re.test(v) ? v : null);
  // Lien de Stripe seulement : https, hôte stripe.com ou un sous-domaine (invoice.stripe.com pour la page, pay.stripe.com pour le PDF).
  function lienStripe(u) {
    if (typeof u !== "string" || u.length > 2000 || /[\s"<>]/.test(u)) return null;
    const m = /^https:\/\/([a-z0-9.-]+)(?::443)?(\/[^#]*)?$/i.exec(u); if (!m) return null;
    const h = m[1].toLowerCase();
    return h === "stripe.com" || h.endsWith(".stripe.com") ? u : null;
  }
  const seconde = x => (typeof x === "number" && Number.isFinite(x) && x > 0 ? Math.floor(x) : null);
  // Période de service : lignes de montant positif ou nul (une montée d'offre facturée tout de suite porte une ligne négative, la part non
  // utilisée de l'ancienne offre) ; du plus tôt au plus tard. Une ligne ponctuelle (option, frais) a début = fin : pas de période.
  function periode(f) {
    const l = (f.lines && Array.isArray(f.lines.data) ? f.lines.data : []).filter(x => x && !(typeof x.amount === "number" && x.amount < 0) && x.period)
      .map(x => [seconde(x.period.start), seconde(x.period.end)]).filter(([a, b]) => a && b && b > a);
    return l.length ? { debut: Math.min(...l.map(x => x[0])), fin: Math.max(...l.map(x => x[1])) } : { debut: null, fin: null };
  }
  function abonnementDe(f) {
    const det = (f.parent && f.parent.subscription_details) || f.subscription_details || {};
    return accepte(ident(f.subscription), RE.abonnement) || accepte(ident(det.subscription), RE.abonnement);
  }
  // Événement Stripe (déjà vérifié par sa signature) -> facture à envoyer, ou null. Ne lève jamais d'erreur : le nœud qui l'appelle répond à Stripe.
  function factureDeEvenement(ev) {
    if (!ev || typeof ev !== "object" || ev.type !== "invoice.paid" || !ev.data || !ev.data.object) return null;
    const f = ev.data.object;
    return factureValide({ facture_id: f.id, numero: f.number, montant_paye: f.amount_paid, devise: f.currency, abonnement: abonnementDe(f), client: ident(f.customer),
      email: f.customer_email, url_facture: f.hosted_invoice_url, url_pdf: f.invoice_pdf, paye_le: f.status_transitions && f.status_transitions.paid_at,
      debut: periode(f).debut, fin: periode(f).fin, livemode: !!ev.livemode, evenement_id: typeof ev.id === "string" ? ev.id.slice(0, 80) : null });
  }
  // Facture reçue par le sous-workflow (même forme) : tout est recontrôlé, rien n'est pris tel quel. null = rien à envoyer.
  // Montant : entier de centimes strictement positif ; sans identifiant de facture, sans numéro ou sans page de facture : rien (le bouton est le
  // cœur de l'email). Email du client absent ou illisible : gardé à null (le sous-workflow lève alors une erreur : workflow d'erreur, PJ prévenu).
  function factureValide(x) {
    if (!x || typeof x !== "object") return null;
    const montant = typeof x.montant_paye === "number" && Number.isInteger(x.montant_paye) ? x.montant_paye : null;
    const facture_id = accepte(x.facture_id, RE.facture), numero = accepte(x.numero, RE.numero), url_facture = lienStripe(x.url_facture);
    if (!facture_id || !numero || !url_facture || montant === null || montant <= 0) return null;
    const devise = typeof x.devise === "string" && /^[a-z]{3}$/i.test(x.devise) ? x.devise.toLowerCase() : null;
    const email = typeof x.email === "string" && RE.email.test(x.email.trim()) && x.email.trim().length <= 254 ? x.email.trim().toLowerCase() : null;
    const debut = seconde(x.debut), fin = seconde(x.fin);
    return { facture_id, numero, montant_paye: montant, devise: devise || "eur", abonnement: accepte(x.abonnement, RE.abonnement), client: accepte(x.client, RE.client),
      email, url_facture, url_pdf: lienStripe(x.url_pdf), paye_le: seconde(x.paye_le), debut: debut && fin && fin > debut ? debut : null, fin: debut && fin && fin > debut ? fin : null,
      livemode: x.livemode === true, evenement_id: typeof x.evenement_id === "string" ? x.evenement_id.slice(0, 80) : null };
  }
  // Idempotence (aucune table ajoutée) : la réservation est une ligne de la table existante stripe_evenements (clé primaire = identifiant), créée
  // AVANT l'envoi par PostgREST avec « Prefer: resolution=ignore-duplicates,return=representation » (insert … on conflict do nothing returning *) :
  // la première demande reçoit sa ligne, toute autre reçoit une réponse vide. Préfixe « facture: » : jamais un evt_… de Stripe, donc jamais vu
  // comme un événement déjà appliqué par appliquer_evenement_stripe ; stripe_subscription et cree vides : la règle « événement plus récent » de la
  // même fonction ne la voit pas. Effacée par purger_donnees au bout d'un an, comme les événements.
  const cleReservation = idFacture => "facture:" + idFacture;
  // reponses : éléments rendus par le nœud HTTP (un par ligne insérée ; un élément vide {} si la réponse est vide, option « Always Output Data »).
  function reservationAcceptee(reponses, idFacture) {
    const l = (Array.isArray(reponses) ? reponses : [reponses]).map(r => (r && r.json !== undefined ? r.json : r));
    return l.some(r => r && typeof r === "object" && r.id === cleReservation(idFacture));
  }
  // Filtres PostgREST du commerce de la facture : abonnement OU client Stripe (abonnements), puis client Stripe (commandes_options, option payée).
  // Identifiants déjà contrôlés (lettres, chiffres, souligné) : rien d'autre n'entre dans l'adresse.
  function filtreAbonnements(f) {
    const c = [f.abonnement && "stripe_subscription.eq." + f.abonnement, f.client && "stripe_customer.eq." + f.client].filter(Boolean);
    return c.length ? "or=(" + c.join(",") + ")" : "id=is.null";
  }
  const filtreOptions = f => (f.client ? "stripe_customer=eq." + f.client : "id=is.null");
  // Lignes lues (abonnements d'abord, puis commandes d'options) -> {id, nom, langue} du commerce, ou null. Langue : fr, en ou nl, sinon fr
  // (même règle que la bienvenue). Une réponse illisible (erreur de la base, nœud en « continuer ») vaut « aucun commerce ».
  function commerceDe(...listes) {
    for (const l of listes) for (const r0 of (Array.isArray(l) ? l : [l])) {
      const r = r0 && r0.json !== undefined ? r0.json : r0, c = r && r.commerces;
      if (r && typeof r.commerce_id === "string" && /^[0-9a-f-]{36}$/i.test(r.commerce_id))
        return { id: r.commerce_id, nom: c && typeof c.nom === "string" && c.nom.trim() ? c.nom.trim().slice(0, 120) : null, langue: c && ["fr", "en", "nl"].includes(c.langue) ? c.langue : "fr" };
    }
    return null;
  }
  // PDF reçu : seulement s'il commence par « %PDF- » et pèse moins de 10 Mo ; sinon l'email part avec le lien seul.
  function pdfValide(octets) {
    if (!octets || typeof octets.length !== "number" || octets.length < 5 || octets.length > 10 * 1024 * 1024) return false;
    return String.fromCharCode(octets[0], octets[1], octets[2], octets[3], octets[4]) === "%PDF-";
  }
  const nomFichier = numero => "Facture-BoostImpact-" + String(numero).replace(/[^A-Za-z0-9-]/g, "") + ".pdf";
  return { factureDeEvenement, factureValide, lienStripe, periode, cleReservation, reservationAcceptee, filtreAbonnements, filtreOptions, commerceDe, pdfValide, nomFichier, RE };
})();
// ---- Nœud « Lire la facture » : facture reçue du workflow Stripe, recontrôlée (montant payé > 0, liens de Stripe seulement). Rien à envoyer : aucun élément.
// Sans adresse email lisible : erreur AVANT toute réservation (workflow d'erreur, PJ prévenu ; la facture reste envoyable une fois corrigée).
const f = FACTURE_STRIPE.factureValide($input.first().json);
if (!f) return [];
if (!f.email) throw new Error('Facture ' + f.numero + ' (' + f.facture_id + ') : aucune adresse email lisible sur la facture Stripe, email de facture non envoyé. L\'envoyer à la main depuis Stripe.');
return [{json: Object.assign(f, {filtre_abonnements: FACTURE_STRIPE.filtreAbonnements(f), filtre_options: FACTURE_STRIPE.filtreOptions(f)})}];

// Emails de BoostImpact au commerçant : bilan du mois (le 1er) et « N contenus à valider ». HTML sobre et texte brut, dans la langue du commerce.
// Recopié tel quel dans les nœuds Code des workflows n8n (n8n/build_maj_membre.py) et testé par moteur/tests/test_courriels.js.
// Charte : pas d'emoji, pas de dégradé, pas d'orange, pas de trait coloré devant un libellé. Charte du site, direction « A · Plein jour » (31/10/2026,
// lot courriels-charte-3110, même charte que les emails de l'audit, moteur/audit/email_audit.py) : blanc, texte encre #121614, gris #4E5652, surface
// #F2F3F1, vert du logo #7CCE12 en aplat pour les boutons (texte encre dessus), liens à l'encre soulignés, titres en Newsreader, texte en Hanken
// Grotesk ; plus de bleu nuit ni d'or. Emails au commerçant : mise en page commune MISE_EN_PAGE ci-dessous. Emails à PJ, demande d'avis, prospection :
// page(), sobre (encre, gris, blanc ; Hanken Grotesk, Arial en repli), sans logo. Testé aussi par moteur/tests/test_emails_gabarit.js.
// Aucun chiffre n'est inventé : une valeur absente (null) est dite « non lue », jamais remplacée.
// Langues (17/10/2026) : un email adressé à un commerçant ou à ses clients sort dans la langue du commerce (commerces.langue : « fr », « en »,
// « nl » = néerlandais de Belgique, vouvoiement « u ») ; toute autre valeur, ou aucune : français, identique octet pour octet à celui d'avant
// (moteur/tests/test_courriels_langues.js). Les emails à PJ restent en français.
const MOIS = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"];
// page() : encre (--encre, 18,3:1 sur blanc), gris (--gris, 7,6:1 sur blanc), filet (--filet-clair, l'encre à 12 %), fond blanc, vert du logo
// (--accent) pour l'aplat du bouton ; valeurs de site/style.css (:root).
const ENCRE = "#121614", GRIS = "#4E5652", FILET = "rgba(18,22,20,.12)", FOND = "#FFFFFF", VERT = "#7CCE12";
const SANS_PAGE = "'Hanken Grotesk',Arial,Helvetica,sans-serif", POLICES_SITE = "https://boostimpact.agency/fonts/";
const langueEmail = x => x === "en" || x === "nl" ? x : "fr";
const MOIS_LANGUE = { fr: MOIS, en: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
  nl: ["januari", "februari", "maart", "april", "mei", "juni", "juli", "augustus", "september", "oktober", "november", "december"] };
const LOCALE = { fr: "fr-FR", en: "en-GB", nl: "nl-BE" }, HTML_LANG = { fr: "fr", en: "en", nl: "nl-BE" };

const echapper = s => String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const nombre = (x, lg) => langueEmail(lg) === "en" ? String(x) : String(x).replace(".", ",");
const pluriel = (n, un, plusieurs) => n + " " + (n > 1 ? plusieurs : un);
function moisLettres(iso, lg) { const [a, m] = String(iso).split("-"); return MOIS_LANGUE[langueEmail(lg)][+m - 1] + " " + a; }
// « 1er octobre » en français, « 1 October », « 1 oktober » ; l'année seulement en changeant d'année.
function premierDuMois(m, lg) { return (langueEmail(lg) === "fr" ? "1er " : "1 ") + MOIS_LANGUE[langueEmail(lg)][(m + 12) % 12]; }
function premierDuMoisSuivant(iso, lg) { const [a, m] = String(iso).split("-").map(Number); return premierDuMois(m, lg) + (m === 12 ? " " + (a + 1) : ""); }
// Lot 6a (15/11/2026) : « 1er octobre » en français (avant : « depuis le 1 octobre »), comme premierDuMois.
function dateLettres(iso, lg) { const d = new Date(iso), t = d.toLocaleDateString(LOCALE[langueEmail(lg)], { day: "numeric", month: "long", timeZone: "Europe/Paris" }); return langueEmail(lg) === "fr" ? t.replace(/^1 /, "1er ") : t; }
// Date et heure de Paris en toutes lettres (27/10/2026) : « 28 octobre à 18 h », « 28 octobre à 18 h 05 » ; « 28 October at 18:00 (Paris time) » ;
// « 28 oktober om 18.00 uur ». Minute tronquée : l'heure écrite n'est jamais plus tard que l'heure réelle.
function dateHeure(iso, lg) {
  const l = langueEmail(lg), p = {};
  new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/Paris", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date(iso)).forEach(x => { p[x.type] = x.value; });
  const h = String(+p.hour), m = p.minute, j = dateLettres(iso, l);
  return l === "en" ? `${j} at ${p.hour}:${m} (Paris time)` : l === "nl" ? `${j} om ${h}.${m} uur` : `${j} à ${h} h${m === "00" ? "" : " " + m}`;
}
function adresse(urlEspace, suite) {
  const u = String(urlEspace || "").replace(/\/+$/, "");
  if (!/^https:\/\/[^\s"<>]+$/.test(u)) throw new Error("adresse de l'espace absente ou non https (variable RENOM_URL_ESPACE)");
  return u + (suite || "/");
}
// Langue des pages ouvertes depuis un email (lot 1, 15/11/2026) : valider.html et avis.html prennent ?lang= avant tout (espace/web/i18n.js) ;
// un email anglais ou néerlandais ouvre donc la page dans sa langue, même si le navigateur garde un autre choix. Français : rien d'ajouté (langue
// par défaut, liens inchangés). « suite » : chemin, avec ou sans requête, avec ou sans #jeton.
function avecLangue(suite, lg) {
  if (lg !== "en" && lg !== "nl") return suite;
  const i = suite.indexOf("#"), chemin = i < 0 ? suite : suite.slice(0, i), ancre = i < 0 ? "" : suite.slice(i);
  return chemin + (chemin.includes("?") ? "&" : "?") + "lang=" + lg + ancre;
}
// Adresses de l'équipe (variable n8n RENOM_EMAIL_PJ, 27/10/2026, audit du parcours, constat 26) : une adresse, ou plusieurs séparées par des virgules
// (ou des points-virgules) pour que PJ et Pascal reçoivent chacun chaque alerte. Rend « a@x.fr, b@y.be » (espaces retirés, sans doublon), ou null
// si la liste est vide ou si une adresse est invalide : l'alerte échoue alors (workflow d'erreur) au lieu de partir à moitié.
function adressesEquipe(x) {
  const l = String(x == null ? "" : x).split(/[,;]/).map(s => s.trim()).filter(Boolean);
  return l.length && l.every(s => /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]{2,}$/.test(s)) ? [...new Set(l)].join(", ") : null;
}

// Pied légal de chaque email (site/legal.json, seule source ; règlement britannique 2015/17, règles 24 et 25 : nom, lieu d'immatriculation,
// numéro, siège). page() l'ajoute au HTML, avecPied() au texte brut. Dans les nœuds Code de n8n, la ligne « require » ci-dessous est remplacée
// par le contenu de legal.json (outils/legal.py, injecter_legal_js, appelé par n8n/build_*.py).
const LEGAL = {"_lisez_moi":"Source unique des mentions légales (pages de site/, pieds de page de site/ et de espace/web/, pieds légaux des emails du moteur et de n8n). Une valeur encore à compléter commence par l'un des marqueurs de outils/legal.py (MARQUES) et s'affiche en gras sur les pages. Après toute modification : python3 outils/legal.py (réécrit les pages), puis python3 n8n/build_automatisations.py, build_maj_membre.py, build_ordre10.py, build_audit.py et python3 moteur/avis/build_workflow.py (régénèrent les emails). Le test moteur/tests/test_legal.py refuse toute page en retard sur ce fichier.","nom_commercial":"BoostImpact","societe":{"denomination":"Girlden LTD","forme":"société à responsabilité limitée de droit anglais (private limited company)","numero":"14837617","registre":"Companies House","pays_immatriculation":"Angleterre et au pays de Galles","siege":"71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni","capital":"1 GBP (déclaration de capital à l'immatriculation, Companies House, 1er mai 2023)","tva":"Société établie au Royaume-Uni, non immatriculée à la TVA dans l'Union européenne. TVA non facturée : autoliquidation par le Client (France : article 283, 2 du code général des impôts ; Belgique : article 51, § 2, alinéa 1er, 1° du Code belge de la TVA ; article 196 de la directive 2006/112/CE)"},"directeur_publication":"Pierre-Jean Deàk Grisoni","contact":{"email":"info@boostimpact.agency","telephone":"sur demande, par email"},"site_url":"https://boostimpact.agency","hebergement":{"pages_production":"cloudflare_pages","fournisseurs":{"cloudflare_pages":{"nom":"Cloudflare, Inc. (service Cloudflare Pages)","adresse":"101 Townsend St., San Francisco, CA 94107, États-Unis","telephone":"+1 650 319 8930","source":"https://www.cloudflare.com/en/website-terms/ (lue le 25/10/2026)"},"supabase":{"nom":"Supabase Pte. Ltd.","adresse":"65 Chulia Street #38-02/03, OCBC Centre, Singapour 049513","telephone":"non publié (contact : legal@supabase.com)","source":"https://supabase.com/terms (lue le 13/10/2026, adresse présentée comme « place of business »)"}}},"documents":{"version":"17 novembre 2026, version 3"},"facturation":{"premier_mois":"le premier mois, ou la première année en paiement annuel, est facturé en entier le jour de la souscription, sans calcul au prorata ; l'abonnement se renouvelle ensuite de date à date, chaque mois ou chaque année selon le rythme de paiement choisi","moyen_paiement":"carte bancaire, par Stripe","taux_penalites":"taux de refinancement le plus récent de la Banque centrale européenne, majoré de 10 points"},"frais_mise_en_route":{"actif":true,"montant_ht":"190","offerts_paiement":"annuel","offres":["standard","premium"],"offerts_apres_option":"visibilite_ia"},"droit_applicable":"pays_client","fournisseur_email":"Google Workspace (Google Ireland Limited, Gordon House, Barrow Street, Dublin 4, Irlande)","pied_email":"{nom_commercial} est un nom commercial de {denomination}, société immatriculée en {pays_immatriculation} ({registre}) sous le numéro {numero}. Siège : {siege}."};
// Anglais et néerlandais : même phrase que pied_texte_en et pied_texte_nl d'outils/legal.py (TRADUCTIONS, TRADUCTIONS_NL), avec la valeur française
// qu'elles traduisent. Si legal.json a changé sans que la traduction suive, le pied reste en français (jamais une valeur fausse) ; le test
// moteur/tests/test_courriels_langues.js compare ces phrases à celles d'outils/legal.py.
const PIED_FR = "{nom_commercial} est un nom commercial de {denomination}, société immatriculée en {pays_immatriculation} ({registre}) sous le numéro {numero}. Siège : {siege}.";
const PIED_LANGUES = {
  en: { gabarit: "{nom_commercial} is a trading name of {denomination}, a company registered in {pays_immatriculation} ({registre}) under number {numero}. Registered office: {siege}.",
    valeurs: { pays_immatriculation: ["Angleterre et au pays de Galles", "England and Wales"],
      siege: ["71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni", "71-75 Shelton Street, Covent Garden, London WC2H 9JQ, United Kingdom"] }, confidentialite: "Privacy: ", page: "/en/privacy.html" },
  nl: { gabarit: "{nom_commercial} is een handelsnaam van {denomination}, een vennootschap ingeschreven in {pays_immatriculation} ({registre}) onder nummer {numero}. Zetel: {siege}.",
    valeurs: { pays_immatriculation: ["Angleterre et au pays de Galles", "Engeland en Wales"],
      siege: ["71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni", "71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Verenigd Koninkrijk"] }, confidentialite: "Privacy: ", page: "/nl/privacy.html" },
};
// Langue du pied : celle demandée si sa traduction est à jour de legal.json, sinon le français.
function langueDuPied(lg) {
  const t = PIED_LANGUES[langueEmail(lg)], s = LEGAL.societe;
  return t && LEGAL.pied_email === PIED_FR && Object.entries(t.valeurs).every(([k, [fr]]) => s[k] === fr) ? langueEmail(lg) : "fr";
}
function piedLegalTexte(lg) {
  const s = LEGAL.societe, p = langueDuPied(lg);
  if (p === "fr") return LEGAL.pied_email.replace(/\{(\w+)\}/g, (m, k) => k === "nom_commercial" ? LEGAL.nom_commercial : s[k]);
  const t = PIED_LANGUES[p];
  return t.gabarit.replace(/\{(\w+)\}/g, (m, k) => k === "nom_commercial" ? LEGAL.nom_commercial : t.valeurs[k] ? t.valeurs[k][1] : s[k]);
}
function lienConfidentialite(lg) {
