// Ce que nous améliorons le mois prochain (ce qui attend la validation du commerçant n'y est plus : c'est l'action, en tête du bilan, 20/10/2026).
function ameliorations(b, lg) {
  const T = TEXTES_BILAN[langueEmail(lg)];
  const l = (b.ameliorations || []).map(x => String(x).trim()).filter(Boolean);
  if (b.note_debut != null && b.note_fin != null && b.note_fin < b.note_debut) l.push(T.baisse);
  const neg = (b.themes || []).filter(t => t.negatif > t.positif).map(t => t.theme);
  if (neg.length) l.push(T.themesNegatifs(neg));
  if (!l.length) l.push(T.rythme);
  return l;
}
const majuscule = s => String(s).charAt(0).toUpperCase() + String(s).slice(1);
function bilanEmail(b, commerce, urlEspace) {
  const lg = langueEmail(commerce.langue), T = TEXTES_BILAN[lg], M = MISE_EN_PAGE, sep = lg === "fr" ? " : " : ": ";
  const nom = commerce.nom, mois = moisLettres(b.mois, lg), url = adresse(urlEspace), source = SOURCE_PERF.replace(/hl=fr$/, "hl=" + T.hl);
  const note = v => v == null ? T.nonLue : T.note(nombre(v, lg));
  const avis = b.avis_obtenus == null ? T.nonLus : b.avis_obtenus_source === "google" ? String(b.avis_obtenus) : T.avisBase(b.avis_obtenus);
  const fait = [[T.reponses, String(b.reponses_publiees)], [T.publications, String(b.publications)]];
  const finMois = premierDuMoisSuivant(b.mois, lg);
  const evolue = [[T.noteAu(premierDuMois(+String(b.mois).split("-")[1] - 1, lg)), note(b.note_debut)], [T.noteAu(finMois), note(b.note_fin)], [T.avisMois, avis]];
  const P = b.performance;
  if (P) {
    evolue.push([T.appels, String(P.appels || 0)], [T.itineraires, String(P.itineraires || 0)], [T.clicsSite, String(P.clics_site || 0)]);
    if (P.vues != null) evolue.push([T.vues, String(P.vues)]);
    if (P.reservations) evolue.push([T.reservations, String(P.reservations)]);
  }
  const perfNote = P ? T.perfNote : "";
  const themes = (b.themes || []).filter(t => t && t.theme).map(t => [majuscule(t.theme), T.compte(t.positif || 0, t.negatif || 0)]);
  const Th = themes.map(([t, c]) => t + sep + c);
  const prochain = ameliorations(b, lg);
  const aValider = b.a_valider > 0, attente = aValider ? T.attente(b.a_valider) : T.rienAttente;
  const sujet = T.sujet(mois, nom), mots = M.MOTS[lg];
  const explication = b.avis_obtenus_source === "google" ? T.explicationGoogle : T.explicationBase;
  // Ce que le commerçant doit faire vient en premier : ce qui attend sa validation, avec le seul bouton de l'email ; sinon, le bouton ferme le bilan.
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(+b.reponses_publiees || 0, +b.publications || 0), repere: nom, h1: T.h1(mois), chapo: T.chapo(nom),
    faits: [[T.fReponses, String(b.reponses_publiees)], [T.fPublications, String(b.publications)], [T.fNote(finMois), majuscule(note(b.note_fin))]],
    corps: [M.p(echapper(T.bonjour), { couleur: M.C.texte }), M.p(echapper(T.voici(mois, nom)), { marge: "0 0 24px 0" }),
      aValider ? M.encart(attente, M.p(echapper(T.attenteSuite(b.a_valider)), { marge: "0", taille: 15 }) + M.bouton(url, T.valider, { marge: "14px 0 0 0" }), "0 0 32px 0") : "",
      M.h2(T.fait), M.lignes(fait),
      M.h2(T.evolue), M.lignes(evolue),
      P ? M.p(echapper(perfNote) + " " + M.lienTexte(source, T.aide, M.C.texteDiscret), { marge: "-4px 0 28px 0", taille: 13, couleur: M.C.texteDiscret }) : "",
      themes.length ? M.h2(T.disent) + M.liste(themes) : "",
      M.h2(T.ameliorons), M.liste(prochain.map(x => [x, ""]), false),
      aValider ? "" : M.p(echapper(attente), { couleur: M.C.texte, style: "font-weight:600" }) + M.bouton(url, T.ouvrir),
      M.p(echapper(explication), { marge: "0 0 8px 0", taille: 13, couleur: M.C.texteDiscret })],
    pied: [T.pied] });
  const texte = [T.bonjour, ``, T.voici(mois, nom), ``,
    ...(aValider ? [attente + " " + T.attenteSuite(b.a_valider), T.valider + sep + url, ``] : []),
    T.fait, ...fait.map(([l, v]) => `${l}${sep}${v}`), ``,
    T.evolue, ...evolue.map(([l, v]) => `${l}${sep}${v}`), ...(P ? [perfNote + T.source + source] : []), ``,
    ...(themes.length ? [T.disent, ...Th, ``] : []),
    T.ameliorons, ...prochain, ``,
    ...(aValider ? [] : [attente, T.espace + url, ``]),
    explication, ``, mots.question, mots.equipe, ``,
    T.pied].join("\n");
  return { sujet, html, texte: avecPied(texte, lg) };
}

// ---- Contenus à valider : items = [{jeton, objet: "contenu"|"commentaire", expire_le, contenu: {type, format, legende, publication_auto_le},
//      commentaire: {reseau, texte}}] ; commerce = {nom, langue, delegation_offre}. Validation SANS mot de passe : chaque lien
//      (valider.html#<jeton>) sert une fois.
// Texte selon l'offre (27/10/2026, audit du parcours, constat 17 ; CGV article 8) : « Rien n'est publié sans votre accord. » seulement quand c'est
// vrai. Mode délégation du Premium signé : chaque contenu porte contenu.publication_auto_le (notifications_validation_du_soir, schema.sql : envoi
// + 48 h) et l'email dit « Sans réponse de votre part, ce contenu sera publié à partir du <date heure> » (« à partir du » : la validation tacite
// passe à l'heure, puis le contenu part au créneau suivant). Offre avec délégation (commerce.delegation_offre) et commentaire dans l'email : rien
// de promis (l'équipe peut répondre aux commentaires du Premium). Sinon, la phrase d'avant.
const TEXTES_VALIDATION = {
  fr: { commentaire: "Réponse à un commentaire", sansTexte: "(sans texte)", story: "Story", video: "Vidéo", publication: "Publication",
    commentaireVide: "Commentaire", contenus: ["publication", "publications"], elements: ["élément", "éléments"], sujet: (q, n) => `${q} à valider pour ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "attendent" : "attend"} votre validation pour ${n}. Un clic suffit, sans mot de passe.`, voir: "Voir et valider",
    h1: (n, q) => (n === 1 ? q.replace(/^1 publication/, "Une publication").replace(/^1 élément/, "Un élément") : q) + " à valider.", chapo: "Rien n'est publié sans votre accord.", apercu: (q, n) => `${q} pour ${n}. Un clic suffit, sans mot de passe.`,
    expire: d => `Chaque lien sert une seule fois et expire le ${d}.`, aussi: l => `Vous pouvez aussi tout valider depuis ${l}.`, votreEspace: "votre espace", espace: "Votre espace : ", separateur: " : ",
    transfert: "Ne transférez pas ce message : chaque lien permet de valider à votre place.",
    auto1: d => `Sans réponse de votre part, cette publication sera mise en ligne à partir du ${d}.`, autoN: "Sans réponse de votre part, chaque publication sera mise en ligne à partir de la date indiquée.",
    auto: d => `Sans réponse de votre part : publié à partir du ${d}.` },
  en: { commentaire: "Reply to a comment", sansTexte: "(no text)", story: "Story", video: "Video", publication: "Post",
    commentaireVide: "Comment", contenus: ["post", "posts"], elements: ["item", "items"], sujet: (q, n) => `${q} to approve for ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "are" : "is"} awaiting your approval for ${n}. One click is enough, no password needed.`, voir: "View and approve",
    h1: (n, q) => (n === 1 ? q.replace(/^1 /, "One ") : q) + " to approve.", chapo: "Nothing is published without your approval.", apercu: (q, n) => `${q} for ${n}. One click is enough, no password needed.`,
    expire: d => `Each link can be used only once and expires on ${d}.`, aussi: l => `You can also approve everything from ${l}.`, votreEspace: "your account", espace: "Your account: ", separateur: ": ",
    transfert: "Do not forward this message: each link lets someone approve on your behalf.",
    auto1: d => `If you do not reply, this post will be published from ${d}.`, autoN: "If you do not reply, each post will be published from the date shown.",
    auto: d => `If you do not reply: published from ${d}.` },
  nl: { commentaire: "Antwoord op een reactie", sansTexte: "(zonder tekst)", story: "Story", video: "Video", publication: "Post",
    commentaireVide: "Reactie", contenus: ["post", "posts"], elements: ["item", "items"], sujet: (q, n) => `${q} om goed te keuren voor ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "wachten" : "wacht"} op uw goedkeuring voor ${n}. Eén klik volstaat, zonder wachtwoord.`, voir: "Bekijken en goedkeuren",
    h1: (n, q) => (n === 1 ? q.replace(/^1 /, "Eén ") : q) + " om goed te keuren.", chapo: "Niets wordt gepubliceerd zonder uw akkoord.", apercu: (q, n) => `${q} voor ${n}. Eén klik volstaat, zonder wachtwoord.`,
    expire: d => `Elke link werkt maar één keer en verloopt op ${d}.`, aussi: l => `U kunt ook alles goedkeuren vanuit ${l}.`, votreEspace: "uw klantenzone", espace: "Uw klantenzone: ", separateur: ": ",
    transfert: "Stuur dit bericht niet door: met elke link kan iemand in uw plaats goedkeuren.",
    auto1: d => `Zonder antwoord van u wordt deze post gepubliceerd vanaf ${d}.`, autoN: "Zonder antwoord van u wordt elke post gepubliceerd vanaf de vermelde datum.",
    auto: d => `Zonder antwoord van u: gepubliceerd vanaf ${d}.` },
