}
function extrait(it, lg) {
  const T = TEXTES_VALIDATION[langueEmail(lg)];
  const t = it.objet === "commentaire" ? (it.commentaire && it.commentaire.texte) || T.commentaireVide : (it.contenu && it.contenu.legende) || "";
  const plat = String(t).replace(/\s+/g, " ").trim();
  // Lot 8 (copywriter, tour 6 : « Story : » qui finit dans le vide) : une story sans légende le dit.
  if (!plat && it.objet !== "commentaire") return T.sansTexte;
  return plat.length > 140 ? plat.slice(0, 139).replace(/\s+\S*$/, "") + "..." : plat;
}
// Lot 6a (15/11/2026) : plus aucune réponse d'avis à valider par le commerçant (CGV art. 8 et 9) : la base fait passer tout avis « a_valider » non
// sensible à l'équipe (déclencheur regler_avis_offre, offres.avis_equipe vrai pour les trois offres) et le workflow d'avis écrit « escalade » ; une
// ligne « avis » qui arriverait quand même n'est pas annoncée (branche « réponses d'avis à valider » retirée).
function notificationEmail(items, commerce, urlEspace) {
  items = (items || []).filter(i => i.objet !== "avis");
  if (!items.length) throw new Error("aucun élément à annoncer");
  const lg = langueEmail(commerce.langue), T = TEXTES_VALIDATION[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const n = items.length, toutContenu = items.every(i => i.objet === "contenu");
